// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListActivities List activities
	// (GET /api/activities)
	ListActivities(w http.ResponseWriter, r *http.Request, params ListActivitiesParams)
	// CreateActivity Create a manual activity
	// (POST /api/activities)
	CreateActivity(w http.ResponseWriter, r *http.Request)
	// UploadActivity Upload a FIT, GPX or TCX file
	// (POST /api/activities/uploads)
	UploadActivity(w http.ResponseWriter, r *http.Request)
	// GetActivity Activity detail
	// (GET /api/activities/{id})
	GetActivity(w http.ResponseWriter, r *http.Request, id ActivityID)
	// SetActivityAnnotation Set what the user adds to an activity
	// (PUT /api/activities/{id}/annotation)
	SetActivityAnnotation(w http.ResponseWriter, r *http.Request, id ActivityID)
	// GetActivityComparison Two activities aligned for overlaying
	// (GET /api/activities/{id}/comparison)
	GetActivityComparison(w http.ResponseWriter, r *http.Request, id ActivityID, params GetActivityComparisonParams)
	// AddActivityEdit Edit an activity
	// (POST /api/activities/{id}/edits)
	AddActivityEdit(w http.ResponseWriter, r *http.Request, id ActivityID)
	// UndoActivityEdit Undo one edit
	// (DELETE /api/activities/{id}/edits/{editId})
	UndoActivityEdit(w http.ResponseWriter, r *http.Request, id ActivityID, editId int64)
	// ListLaps Laps of an activity
	// (GET /api/activities/{id}/laps)
	ListLaps(w http.ResponseWriter, r *http.Request, id ActivityID, params ListLapsParams)
	// ListSwimLengths Pool lengths of an activity
	// (GET /api/activities/{id}/lengths)
	ListSwimLengths(w http.ResponseWriter, r *http.Request, id ActivityID, params ListSwimLengthsParams)
	// ListStrengthSets Strength sets of an activity
	// (GET /api/activities/{id}/sets)
	ListStrengthSets(w http.ResponseWriter, r *http.Request, id ActivityID, params ListStrengthSetsParams)
	// GetActivityStreams Sample streams of an activity
	// (GET /api/activities/{id}/streams)
	GetActivityStreams(w http.ResponseWriter, r *http.Request, id ActivityID, params GetActivityStreamsParams)
	// Login Log in
	// (POST /api/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout Log out and end the session
	// (POST /api/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// Register Create an account and log in
	// (POST /api/auth/register)
	Register(w http.ResponseWriter, r *http.Request)
	// GetConfig Frontend settings
	// (GET /api/config)
	GetConfig(w http.ResponseWriter, r *http.Request)
	// DeleteGarminConnection Disconnect Garmin
	// (DELETE /api/garmin)
	DeleteGarminConnection(w http.ResponseWriter, r *http.Request)
	// GetGarminConnection Garmin connection status
	// (GET /api/garmin)
	GetGarminConnection(w http.ResponseWriter, r *http.Request)
	// GetGarminBackfill Onboarding backfill progress
	// (GET /api/garmin/backfill)
	GetGarminBackfill(w http.ResponseWriter, r *http.Request)
	// StartGarminBackfill Start the onboarding backfill
	// (POST /api/garmin/backfill)
	StartGarminBackfill(w http.ResponseWriter, r *http.Request)
	// ListGarminBackfillFailures Activities the backfill could not import
	// (GET /api/garmin/backfill/failures)
	ListGarminBackfillFailures(w http.ResponseWriter, r *http.Request, params ListGarminBackfillFailuresParams)
	// ResumeGarminBackfill Resume the backfill
	// (POST /api/garmin/backfill/resume)
	ResumeGarminBackfill(w http.ResponseWriter, r *http.Request)
	// SetGarminKey Set the Personal API key
	// (PUT /api/garmin/key)
	SetGarminKey(w http.ResponseWriter, r *http.Request)
	// SyncGarmin Sync Garmin now
	// (POST /api/garmin/sync)
	SyncGarmin(w http.ResponseWriter, r *http.Request)
	// SetGarminSyncInterval Set how often Garmin is synced
	// (PUT /api/garmin/sync-interval)
	SetGarminSyncInterval(w http.ResponseWriter, r *http.Request)
	// ListGear List shoes and bikes
	// (GET /api/gear)
	ListGear(w http.ResponseWriter, r *http.Request, params ListGearParams)
	// CreateGear Add shoes or a bike
	// (POST /api/gear)
	CreateGear(w http.ResponseWriter, r *http.Request)
	// DeleteGear Delete gear
	// (DELETE /api/gear/{id})
	DeleteGear(w http.ResponseWriter, r *http.Request, id GearID)
	// UpdateGear Edit, retire or reactivate gear
	// (PUT /api/gear/{id})
	UpdateGear(w http.ResponseWriter, r *http.Request, id GearID)
	// GetMe Current user and CSRF token
	// (GET /api/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// UpdateMe Update profile settings
	// (PATCH /api/me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// GetHealthz Liveness probe
	// (GET /healthz)
	GetHealthz(w http.ResponseWriter, r *http.Request)
}

